-- Step 17.15: supervised Technical Operations Agent.
create table public.technical_agent_incidents(id uuid primary key default gen_random_uuid(),incident_ref text not null unique,incident_type text not null check(incident_type in('application','integration','database','infrastructure','job','security','backup')),severity text not null check(severity in('low','medium','high','critical')),title text not null,status text not null default 'open' check(status in('open','investigating','mitigated','monitoring','resolved','closed')),assigned_specialist text check(assigned_specialist in('Application & Integration Engineer','Database, Infrastructure & DevOps')),evidence jsonb not null default '{}' check(jsonb_typeof(evidence)='object'),created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default statement_timestamp(),updated_at timestamptz not null default statement_timestamp());create index technical_incidents_queue_idx on public.technical_agent_incidents(status,severity,created_at);
create table public.technical_agent_changes(id uuid primary key default gen_random_uuid(),incident_id uuid references public.technical_agent_incidents(id),change_type text not null check(change_type in('deployment','database','credential','infrastructure','backup_restore','job_retry','security_response')),plan jsonb not null default '{}' check(jsonb_typeof(plan)='object'),rollback_plan jsonb not null default '{}' check(jsonb_typeof(rollback_plan)='object'),status text not null default 'draft' check(status in('draft','tested','awaiting_approval','approved','executing','completed','failed','cancelled')),created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default statement_timestamp());create index technical_changes_status_idx on public.technical_agent_changes(status,created_at);
create table public.technical_agent_approvals(id uuid primary key default gen_random_uuid(),change_id uuid not null references public.technical_agent_changes(id),approval_type text not null check(approval_type in('production_deploy','database_change','credential_rotation','infrastructure_change','backup_restore','destructive_action')),status text not null default 'pending' check(status in('pending','approved','rejected','cancelled')),requested_by uuid not null default auth.uid() references auth.users(id),decided_by uuid references auth.users(id),decision_reason text,requested_at timestamptz not null default statement_timestamp(),decided_at timestamptz,check((status='pending'and decided_by is null and decided_at is null)or(status<>'pending'and decided_by is not null and decided_at is not null)));
create table public.technical_agent_automations(id uuid primary key default gen_random_uuid(),automation_key text not null unique,name text not null,configuration jsonb not null default '{}' check(jsonb_typeof(configuration)='object'),status text not null default 'draft' check(status in('draft','active','paused','archived')),automatic_deploy boolean not null default false check(not automatic_deploy),automatic_database_change boolean not null default false check(not automatic_database_change),automatic_credential_rotation boolean not null default false check(not automatic_credential_rotation),automatic_infrastructure_change boolean not null default false check(not automatic_infrastructure_change),automatic_backup_restore boolean not null default false check(not automatic_backup_restore),automatic_destructive_action boolean not null default false check(not automatic_destructive_action),created_by uuid not null default auth.uid() references auth.users(id),approved_by uuid references auth.users(id),approved_at timestamptz,check(status<>'active'or(approved_by is not null and approved_at is not null)));
create table public.technical_agent_reports(id uuid primary key default gen_random_uuid(),report_type text not null check(report_type in('system_health','incident','reliability','security','backup','subagent_quality')),summary jsonb not null default '{}' check(jsonb_typeof(summary)='object'),generated_at timestamptz not null default statement_timestamp());
create table private.technical_agent_activity(id bigint generated always as identity primary key,incident_id uuid references public.technical_agent_incidents(id) on delete set null,actor_type public.audit_actor_type not null,actor_id uuid references auth.users(id) on delete set null,action text not null,evidence jsonb not null default '{}' check(jsonb_typeof(evidence)='object'),occurred_at timestamptz not null default statement_timestamp());create index technical_activity_timeline_idx on private.technical_agent_activity(occurred_at desc,id desc);
alter table public.technical_agent_incidents enable row level security;alter table public.technical_agent_incidents force row level security;alter table public.technical_agent_changes enable row level security;alter table public.technical_agent_changes force row level security;alter table public.technical_agent_approvals enable row level security;alter table public.technical_agent_approvals force row level security;alter table public.technical_agent_automations enable row level security;alter table public.technical_agent_automations force row level security;alter table public.technical_agent_reports enable row level security;alter table public.technical_agent_reports force row level security;alter table private.technical_agent_activity enable row level security;alter table private.technical_agent_activity force row level security;
revoke all on public.technical_agent_incidents,public.technical_agent_changes,public.technical_agent_approvals,public.technical_agent_automations,public.technical_agent_reports from public,anon,authenticated;revoke all on private.technical_agent_activity from public,anon,authenticated,service_role;grant select,insert,update on public.technical_agent_incidents,public.technical_agent_changes,public.technical_agent_approvals,public.technical_agent_automations to authenticated;grant select on public.technical_agent_reports to authenticated;
create function private.is_step_17_15_technical_admin(p_owner_only boolean default false)returns boolean language sql stable security definer set search_path='' as $$select(select auth.jwt()->>'aal')='aal2'and exists(select 1 from public.user_roles r where r.user_id=(select auth.uid())and r.is_active and r.revoked_at is null and(r.role='owner'::public.app_role or(not p_owner_only and r.role='analyst'::public.app_role)));$$;revoke all on function private.is_step_17_15_technical_admin(boolean) from public,anon,authenticated,service_role;grant execute on function private.is_step_17_15_technical_admin(boolean) to authenticated;
create policy technical_incidents_read on public.technical_agent_incidents for select to authenticated using((select private.is_step_17_15_technical_admin(false)));create policy technical_incidents_write on public.technical_agent_incidents for all to authenticated using((select private.is_step_17_15_technical_admin(false)))with check(created_by=(select auth.uid())and(select private.is_step_17_15_technical_admin(false)));create policy technical_changes_read on public.technical_agent_changes for select to authenticated using((select private.is_step_17_15_technical_admin(false)));create policy technical_changes_write on public.technical_agent_changes for all to authenticated using((select private.is_step_17_15_technical_admin(false)))with check(created_by=(select auth.uid())and status not in('executing','completed')and(select private.is_step_17_15_technical_admin(false)));create policy technical_approvals_read on public.technical_agent_approvals for select to authenticated using((select private.is_step_17_15_technical_admin(false)));create policy technical_approvals_request on public.technical_agent_approvals for insert to authenticated with check(requested_by=(select auth.uid())and status='pending'and(select private.is_step_17_15_technical_admin(false)));create policy technical_approvals_decide on public.technical_agent_approvals for update to authenticated using((select private.is_step_17_15_technical_admin(true)))with check(decided_by=(select auth.uid())and(select private.is_step_17_15_technical_admin(true)));create policy technical_automations_read on public.technical_agent_automations for select to authenticated using((select private.is_step_17_15_technical_admin(false)));create policy technical_automations_write on public.technical_agent_automations for all to authenticated using((select private.is_step_17_15_technical_admin(true)))with check(created_by=(select auth.uid())and not automatic_deploy and not automatic_database_change and not automatic_credential_rotation and not automatic_infrastructure_change and not automatic_backup_restore and not automatic_destructive_action and(select private.is_step_17_15_technical_admin(true)));create policy technical_reports_read on public.technical_agent_reports for select to authenticated using((select private.is_step_17_15_technical_admin(false)));create policy technical_activity_deny on private.technical_agent_activity as restrictive for all to anon,authenticated using(false)with check(false);
create function private.reject_technical_activity_mutation()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception 'technical activity is append-only';end;$$;revoke all on function private.reject_technical_activity_mutation() from public,anon,authenticated,service_role;create trigger technical_activity_immutable before update or delete on private.technical_agent_activity for each row execute function private.reject_technical_activity_mutation();
